// Verifies the Svix signature Resend puts on every webhook.
//
// Paste the signing secret from Resend > Webhooks > (this webhook) below.
// It lives here rather than in an n8n credential because the Code node cannot
// read credentials, and the Crypto node takes its HMAC key as text while a
// Svix key is binary (base64 after "whsec_"). Node's crypto module is not
// allowed in the Code sandbox either, hence the small SHA-256 below.
const SIGNING_SECRET = 'whsec_PASTE_THE_RESEND_SIGNING_SECRET_HERE';
const TOLERANCE_SECONDS = 5 * 60;

const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

const rotr = (x, n) => (x >>> n) | (x << (32 - n));

function sha256(msg) {
  const len = msg.length;
  const padded = Buffer.alloc((((len + 9) + 63) >> 6) << 6);
  msg.copy(padded);
  padded[len] = 0x80;
  padded.writeUInt32BE(Math.floor(len / 0x20000000), padded.length - 8);
  padded.writeUInt32BE((len * 8) >>> 0, padded.length - 4);

  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const W = new Array(64);
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = padded.readUInt32BE(off + i * 4) | 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(W[i - 15], 7) ^ rotr(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = rotr(W[i - 2], 17) ^ rotr(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + W[i]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = Buffer.alloc(32);
  H.forEach((v, i) => out.writeUInt32BE(v >>> 0, i * 4));
  return out;
}

function hmacSha256(key, msg) {
  const block = Buffer.alloc(64);
  (key.length > 64 ? sha256(key) : key).copy(block);
  const inner = Buffer.alloc(64);
  const outer = Buffer.alloc(64);
  for (let i = 0; i < 64; i++) {
    inner[i] = block[i] ^ 0x36;
    outer[i] = block[i] ^ 0x5c;
  }
  return sha256(Buffer.concat([outer, sha256(Buffer.concat([inner, msg]))]));
}

function sameString(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

function verify(headers, rawBody, nowSeconds) {
  const id = headers['svix-id'];
  const timestamp = headers['svix-timestamp'];
  const signatures = headers['svix-signature'];
  if (!id || !timestamp || !signatures) return 'missing svix headers';
  if (SIGNING_SECRET.includes('PASTE')) return 'signing secret not set in the Verify node';

  const age = Math.abs(nowSeconds - Number(timestamp));
  if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) return 'timestamp outside tolerance';

  const key = Buffer.from(SIGNING_SECRET.replace(/^whsec_/, ''), 'base64');
  const signed = Buffer.concat([Buffer.from(`${id}.${timestamp}.`, 'utf8'), rawBody]);
  const expected = hmacSha256(key, signed).toString('base64');
  const matches = signatures
    .split(' ')
    .some((entry) => entry.startsWith('v1,') && sameString(entry.slice(3), expected));
  return matches ? null : 'signature mismatch';
}

// --- n8n entry point ---
const item = $input.first();
const rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
const failure = verify(item.json.headers || {}, rawBody, Math.floor(Date.now() / 1000));
if (failure) return [{ json: { valid: false, reason: failure } }];

const event = JSON.parse(rawBody.toString('utf8'));
return [{ json: { valid: true, type: event.type, email_id: event.data && event.data.email_id } }];

// Turns the received email into a POST /emails body. Resend has no REST
// "forward" call - the SDK's forward() does this same get-then-send.
const FORWARD_TO = 'you@example.com';
const FORWARD_FROM = 'hello@academious.org';

const email = $('Get received email').first().json;
const attachments = $('List attachments').first().json.data || [];

// "Ada Lovelace <ada@example.org>" or a bare address.
const match = /^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/.exec(email.from || '');
const senderName = match ? match[1].trim() : '';
const senderAddress = match ? match[2].trim() : (email.from || '').trim();
const displayName = (senderName || senderAddress || 'unknown sender').replace(/["\\\r\n]/g, '');

const receivedFor = (email.received_for && email.received_for.length ? email.received_for : email.to || []).join(', ');
const banner = `Forwarded from ${senderAddress} to ${receivedFor}`;
const escapeHtml = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const body = {
  from: `"${displayName} via academious" <${FORWARD_FROM}>`,
  to: [FORWARD_TO],
  reply_to: email.reply_to && email.reply_to.length ? email.reply_to : [senderAddress],
  subject: email.subject || '(no subject)',
  text: `${banner}\n\n${email.text || (email.html ? '' : '(empty message)')}`,
};
if (email.html) {
  body.html = `<p style="color:#888;font-size:12px">${escapeHtml(banner)}</p>${email.html}`;
}
if (attachments.length) {
  // Resend fetches each file from its signed download URL itself.
  body.attachments = attachments.map((a) => {
    const out = { path: a.download_url, filename: a.filename || 'attachment' };
    if (a.content_type) out.content_type = a.content_type;
    if (a.content_id) out.content_id = a.content_id.replace(/^<|>$/g, '');
    return out;
  });
}

return [{ json: { body } }];
